#!/usr/bin/env node
// Gate for real WS/Agent/tool evidence, independent of comparison score.
import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';import {fileURLToPath} from 'node:url';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const filename=process.argv[2];assert.ok(filename,'usage: verify-formal.mjs artifact.json');const bytes=fs.readFileSync(filename),a=JSON.parse(bytes);
assert.equal(a.scenario,'turn-steer-attachments-native');assert.deepEqual(a.failures,[]);assert.ok(a.evidence.assertions.length>=8);for(const result of a.evidence.assertions){assert.equal(result.passed,true,result.id);assert.ok(!result.skipped);}
for(const name of['initial','after-steer','after-read']){assert.equal(a.provider[name]?.length,1,name);assert.equal(a.provider[name][0].body.model,'deterministic');}assert.equal(a.provider.unexpected?.length??0,0);assert.equal(a.provider.default?.length??0,0);
const turn=a.steps[1];assert.equal(turn.step.ws,'submit_turn');const steers=turn.answers.filter(answer=>answer.ws==='steer_turn'),permissions=turn.answers.filter(answer=>answer.ws==='permission_decide');assert.equal(steers.length,1);assert.equal(permissions.length,1,'only initial bash permission may be answered');assert.equal(steers[0].frames.find(f=>f.type==='response')?.result?.accepted,true);
const events=turn.frames.filter(f=>f.type==='event').map(f=>f.event).filter(Boolean);assert.equal(events.filter(e=>e.type==='permission_request').length,1,'registered steer file read did not ask an extra unanswered permission');assert.ok(events.some(e=>e.type==='steer_applied'),'queued steer actually applied');
const messages=a.provider['after-steer'][0].body.messages;const strings=messages.filter(m=>m.role==='user').map(m=>typeof m.content==='string'?m.content:JSON.stringify(m.content));assert.ok(strings.some(s=>s.includes('STEER-ATTACH-NOTE')&&s.includes('STEER-REGISTERED-FILE')&&s.includes('[Registered attachment files in this session:]')),'actual model-visible attached content and path note');
const after=a.provider['after-read'][0].body.messages;const tool=after.find(m=>m.role==='tool'&&m.tool_call_id==='call_attachment_read');assert.ok(tool,'real read_file result');assert.ok((typeof tool.content==='string'?tool.content:JSON.stringify(tool.content)).includes('STEER-REGISTERED-FILE'),'tool read exact external attachment bytes');assert.ok(events.some(e=>e.type==='assistant_text_delta'&&e.text==='STEER-ATTACH-OK'));
const lines=Object.values(a.tree).flatMap(file=>file.jsonl??[]);assert.ok(lines.some(line=>JSON.stringify(line).includes('steer-attachment')&&JSON.stringify(line).includes('STEER-REGISTERED-FILE')),'actual attachment steer persisted, not only accepted');
assert.equal(hash(fs.readFileSync(filename)),hash(bytes));console.log(JSON.stringify({passed:true,side:a.side,artifactSha256:hash(bytes),verifierSha256:hash(fs.readFileSync(fileURLToPath(import.meta.url))),steers:1,permissionAnswers:1,fileReads:1}));
